ValidationRule.errorConditionFormula:
OR
(
AND(
QTB_Billing_Country_Name__c ="Canada",
NOT(
OR(
ISPICKVAL(US_Federal_GSA_Pricing__c, "Yes - Canada Public Sector (non-Healthcare)"),
ISPICKVAL(US_Federal_GSA_Pricing__c, "No")
)
)
),
AND(
QTB_Billing_Country_Name__c ="United States",
ISPICKVAL(US_Federal_GSA_Pricing__c, "Yes - Canada Public Sector (non-Healthcare)")
)
)
